	m.HandleFunc("GET "+options.BaseURL+"/api/boards", wrapper.ListBoards)
	m.HandleFunc("POST "+options.BaseURL+"/api/boards", wrapper.CreateBoard)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/boards/{bid}/cards/{cid}", wrapper.DeleteCard)
