	m.HandleFunc("PATCH "+options.BaseURL+"/api/boards/{bid}/columns/{cid}", wrapper.UpdateBoardColumn)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/boards/{id}", wrapper.DeleteBoard)
	m.HandleFunc("GET "+options.BaseURL+"/api/boards/{id}", wrapper.GetBoard)
	m.HandleFunc("PATCH "+options.BaseURL+"/api/boards/{id}", wrapper.UpdateBoard)
	m.HandleFunc("POST "+options.BaseURL+"/api/boards/{id}/cards", wrapper.CreateCard)
	m.HandleFunc("GET "+options.BaseURL+"/api/cards/{id}", wrapper.GetBoardCard)

